import{_ as a,C as r,o,c as i,E as n,a2 as s}from"./chunks/framework.BOeh4kYD.js";const v=JSON.parse('{"title":"State May Persist; Authority Must Be Re-established","description":"","frontmatter":{"title":"State May Persist; Authority Must Be Re-established","date":"2026-09-12","column":"industry-architecture","category":"daily","article_type":"comparative-study","edition":"research-center","research_question":"当当前政策或运行时身份与长寿命智能体会话保留的状态冲突时，下一个外部效果应由哪一来源决定，优先级规则应在哪里执行，拒绝正向工作后又必须保留哪些安全控制？","summary":"Long-lived sessions need retained state, but retention does not preserve sovereignty. Three recent implementations demonstrate revalidation, authoritative replacement, and control-state isolation while preserving stop and recovery operations after positive work is rejected.","sources":["research/analysis/Q-20260912-02-continuity-authority-precedence.md"],"item_id":"Q-20260912-02","lifecycle":"Published","cover":"/assets/covers/daily-2026-09-12-retained-state-current-authority-cover.png","evidence_status":"Completed","citation_status":"Completed","editing_status":"Completed","publication_authorized":true},"headers":[],"relativePath":"en/industry/2026-09-12-retained-state-current-authority.md","filePath":"en/industry/2026-09-12-retained-state-current-authority.md","lastUpdated":1789216147000}'),d={name:"en/industry/2026-09-12-retained-state-current-authority.md"};function l(c,e,u,h,p,m){const t=r("ArticleCover");return o(),i("div",null,[n(t,{image:"/assets/covers/daily-2026-09-12-retained-state-current-authority-cover.png",kicker:"Industry Architecture · Daily Research",title:"State May Persist; Authority Must Be Re-established",summary:"Long-lived sessions need retained state, but retention does not preserve sovereignty. Three recent implementations demonstrate revalidation, authoritative replacement, and control-state isolation while preserving stop and recovery operations after positive work is rejected.",version:"Q-20260912-02",status:"Daily Runtime V5 · 2026-09-12",languageHref:"/zh/industry/2026-09-12-retained-state-current-authority",languageLabel:"中文"}),e[0]||(e[0]=s('<h1 id="state-may-persist-authority-must-be-re-established" tabindex="-1">State May Persist; Authority Must Be Re-established <a class="header-anchor" href="#state-may-persist-authority-must-be-re-established" aria-label="Permalink to &quot;State May Persist; Authority Must Be Re-established&quot;">​</a></h1><p>A session has been running for hours. Its model route, request headers, and project configuration remain valid. Meanwhile, an administrator changes the managed provider requirement, an identity provider acquires a new token, and the workspace moves from trusted to untrusted.</p><p>If the system treats “still present” as “still authoritative,” continuity quietly becomes permanent permission. A long-lived agent does not need to erase all state at every transition. It needs to name what may persist, which source owns current authority, which precedence operator resolves conflict, and where that decision must occur before an effect.</p><p>This article compares three recent merged engineering changes at session, transport, and sandbox layers. Together they support one bounded proposition: <strong>continuity state may remain useful without remaining sovereign. Each effect-bearing operation needs an explicit current authority owner, a deterministic precedence operator, and preserved safe controls before mutation.</strong></p><h2 id="continuity-and-authority-are-orthogonal" tabindex="-1">Continuity and Authority Are Orthogonal <a class="header-anchor" href="#continuity-and-authority-are-orthogonal" aria-label="Permalink to &quot;Continuity and Authority Are Orthogonal&quot;">​</a></h2><p>Retained sessions avoid reconstructing context. Stored request configuration supports a connection before an identity transition. User-global commands preserve personal workflows. Those are continuity benefits.</p><p>Yet a value can remain readable, well-formed, and previously validated after it loses the right to govern the next action. Authority may have moved to managed policy, a current authentication provider, or protected host state. The runtime needs an explicit boundary between usable state and decision-making sovereignty.</p><p>The samples expose three operators:</p><ul><li><strong>revalidation</strong> retains state but compares it with current authority before selected operations;</li><li><strong>replacement</strong> overwrites a lower-authority field once the current authoritative value exists;</li><li><strong>isolation</strong> prevents a lower-trust domain from reading or mutating control state.</li></ul><p>They solve different conflicts and are not interchangeable.</p><h2 id="codex-revalidate-retained-sessions-at-call-time" tabindex="-1">Codex: Revalidate Retained Sessions at Call Time <a class="header-anchor" href="#codex-revalidate-retained-sessions-at-call-time" aria-label="Permalink to &quot;Codex: Revalidate Retained Sessions at Call Time&quot;">​</a></h2><p>The Codex change addresses existing app-server threads. It loads current managed provider requirements independently, then compares the retained provider selection and definition before selected model-driving or state-changing operations.</p><p>The important move is not a universal configuration reload. Ordinary user, project, and system-default configuration does not rewrite the existing thread. Managed requirements are isolated as the authority source. A mismatch, loading failure, or parsing failure rejects the protected request before queue or goal state changes.</p><p>This fail-closed behavior is bounded. Interrupt, realtime stop, and goal pause or clear remain available; realtime routing is outside the check. Positive work that needs current authority stops, while negative controls that reduce activity remain usable.</p><p>The evidence covers enumerated, tested call paths. It does not prove that a future endpoint cannot bypass the check. Call-site completeness must remain an active verification target.</p><h2 id="mcp-typescript-sdk-give-managed-fields-one-owner" tabindex="-1">MCP TypeScript SDK: Give Managed Fields One Owner <a class="header-anchor" href="#mcp-typescript-sdk-give-managed-fields-one-owner" aria-label="Permalink to &quot;MCP TypeScript SDK: Give Managed Fields One Owner&quot;">​</a></h2><p>The Model Context Protocol TypeScript SDK problem lives in HTTP transport. A caller can supply Authorization, protocol version, or session identity, while the transport derives those values from current authentication and session state. Generic merging can preserve both. Case variants can even combine into a malformed multi-value credential.</p><p>The fix initializes standard Fetch Headers from caller input, then uses case-insensitive set operations for transport-managed Authorization, protocol version, and Streamable HTTP session ID. Once the provider has a token, runtime-derived Authorization replaces stale caller Authorization. Before that transition, a configured value can remain usable.</p><p>The operator is field-level replacement, not deletion of all caller configuration. The transport owns named fields and preserves unrelated headers. Authority follows ownership and state transition, not whichever value happens to be written last.</p><p>This resolves identity ambiguity during request construction. It does not prove that a server authorizes the token correctly or that transport identity grants business-operation permission.</p><h2 id="gemini-cli-isolate-control-state-from-lower-trust-execution" tabindex="-1">Gemini CLI: Isolate Control State From Lower-Trust Execution <a class="header-anchor" href="#gemini-cli-isolate-control-state-from-lower-trust-execution" aria-label="Permalink to &quot;Gemini CLI: Isolate Control State From Lower-Trust Execution&quot;">​</a></h2><p>The Gemini CLI change handles a different boundary. Sandbox and untrusted project content should not read or rewrite credential, account, trust, policy-integrity, or environment-secret state. Sandbox profiles and host-path checks reduce that visibility and mutation surface while sanitizing hooks and API-key settings.</p><p>Command loading also distinguishes sources. User-global commands remain available in an untrusted folder, while project and extension commands are excluded. The runtime does not disable every feature after trust falls; it prevents a lower-trust source from promoting itself into a control source.</p><p>This problem cannot be solved by comparison alone. If project code can mutate the policy or credential store consulted by the next check, revalidation merely reads a compromised “current” value. Isolation protects the authority substrate itself.</p><p>The guarantee still depends on host enforcement and correct path resolution. Configuration evidence alone cannot establish complete sandbox security.</p><h2 id="three-operators-three-conflict-classes" tabindex="-1">Three Operators, Three Conflict Classes <a class="header-anchor" href="#three-operators-three-conflict-classes" aria-label="Permalink to &quot;Three Operators, Three Conflict Classes&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Scenario</th><th>Retained state</th><th>Current authority</th><th>Operator</th><th>Primary failure</th></tr></thead><tbody><tr><td>Long-lived session meets new managed policy</td><td>thread provider state</td><td>managed requirement</td><td>revalidate and reject</td><td>startup authorization decay</td></tr><tr><td>Caller header meets current authenticated identity</td><td>static Authorization</td><td>provider token</td><td>field replacement</td><td>dual identity and case merge</td></tr><tr><td>Project execution approaches credential and trust state</td><td>workspace code/config</td><td>protected host store</td><td>isolation</td><td>workspace-to-control escalation</td></tr></tbody></table><p>“Reload everything” destroys valid continuity. “Newest wins” allows a newly written low-trust value to outrank protected state. “Keep the old value until failure” lets expired authority cross the effect boundary. The correct operator depends on field ownership, operation class, and threat model.</p><h2 id="stop-capability-must-survive-rejection" tabindex="-1">Stop Capability Must Survive Rejection <a class="header-anchor" href="#stop-capability-must-survive-rejection" aria-label="Permalink to &quot;Stop Capability Must Survive Rejection&quot;">​</a></h2><p>Fail-closed is often implemented as a master switch: validation fails, so every operation stops. That can lock out recovery. Inability to continue model work should not disable interrupt. Refusal to send stale authentication should not remove unrelated headers. Excluding untrusted project commands does not require removing user-global commands.</p><p>A negative-control policy should enumerate interrupt, stop, pause, clear, rollback, and read-only diagnosis separately, then verify that none can initiate positive work indirectly. Safety is not “nothing moves.” It is “effects requiring current authority do not proceed, while risk can still be reduced.”</p><h2 id="a-minimum-authority-precedence-contract" tabindex="-1">A Minimum Authority-Precedence Contract <a class="header-anchor" href="#a-minimum-authority-precedence-contract" aria-label="Permalink to &quot;A Minimum Authority-Precedence Contract&quot;">​</a></h2><p>Every effect class should declare:</p><table tabindex="0"><thead><tr><th>Contract field</th><th>Question</th></tr></thead><tbody><tr><td>Retained-state identity</td><td>What persists for continuity?</td></tr><tr><td>Current authority source and version</td><td>Who decides now?</td></tr><tr><td>Refresh point</td><td>When is authority obtained or confirmed?</td></tr><tr><td>Precedence operator</td><td>Compare and reject, replace, or isolate?</td></tr><tr><td>Authority-unavailable behavior</td><td>Fail closed, bounded cache, or recovery?</td></tr><tr><td>Mutation boundary</td><td>What is the last point before effect?</td></tr><tr><td>Negative controls</td><td>Which risk-reducing actions remain available?</td></tr><tr><td>Evidence receipt</td><td>How can the applied source and rule be proved?</td></tr></tbody></table><p>The contract is operation-specific. A provider requirement may govern model-driving work but not interrupt. An identity provider may own Authorization but not every header. A sandbox may read business files while remaining unable to reach trust and secret stores.</p><h2 id="test-transitions-not-only-steady-state" tabindex="-1">Test Transitions, Not Only Steady State <a class="header-anchor" href="#test-transitions-not-only-steady-state" aria-label="Permalink to &quot;Test Transitions, Not Only Steady State&quot;">​</a></h2><p>Authority defects cluster at transitions. A useful test matrix covers:</p><ul><li>the same thread before and after a policy update;</li><li>requests before and after token acquisition;</li><li>case variants and every supported HeadersInit form;</li><li>trusted and untrusted workspaces;</li><li>available, unavailable, and malformed authority sources;</li><li>interrupt and rollback while positive work is rejected;</li><li>proof that queue, goal, and external state remain unchanged after rejection.</li></ul><p>These tests are not only regressions. They are executable documentation of the precedence contract.</p><h2 id="boundaries-and-open-questions" tabindex="-1">Boundaries and Open Questions <a class="header-anchor" href="#boundaries-and-open-questions" aria-label="Permalink to &quot;Boundaries and Open Questions&quot;">​</a></h2><p>All three samples are first-party merged code and tests, not independent production outcomes or complete adversarial evaluations. Provider routing, HTTP authentication, and filesystem sandboxing occupy different layers. A shared abstraction must not erase their distinct threat models.</p><p>Fail-closed refresh can reduce availability during policy-service outages. Signed caches may help, but cache validity, applicable operations, and expiry become part of the authority contract. Negative controls must also be monotonic: an operation labeled “pause” must not indirectly launch new work.</p><p>Open questions include how to prove coverage of every effect path, which updates invalidate in-flight work, how authority composes across session, transport, tool server, and external target, how users migrate old sessions without losing unrelated valid work, and how to measure stale-authority prevention without exposing secrets.</p><p><strong>Evidence and citations:</strong></p><ul><li><a href="https://github.com/openai/codex/commit/39d193d72d7959d798642bd3e1496bb8865033b1" target="_blank" rel="noreferrer">Codex managed-provider revalidation for existing threads</a></li><li><a href="https://github.com/modelcontextprotocol/typescript-sdk/commit/b65426158ed9f29aea8ef3dc09ca22d7d9d6f970" target="_blank" rel="noreferrer">MCP TypeScript SDK transport-header precedence</a></li><li><a href="https://github.com/google-gemini/gemini-cli/commit/9c1b0a610534d6f8120964cf2672c07807d8fc90" target="_blank" rel="noreferrer">Gemini CLI sandbox and runtime-state isolation</a></li></ul>',45))])}const f=a(d,[["render",l]]);export{v as __pageData,f as default};
